"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["54238"],{61250(e){e.exports=JSON.parse('{"id":"FIN-567","slug":"interest-income","term":"Interest Income","also_known_as":[],"difficulty":"Intermediate","definition":"Interest income is the money a company or individual earns from lending money or holding interest-bearing assets, such as bank deposits, bonds and loans.","explanation":["Interest income is the opposite of interest expense. When a company keeps cash in interest-bearing accounts, holds bonds or lends money to others, it earns interest, which is recorded as income in the period it is earned.","For example, a company with 5 million in deposits earning 4% a year would record about 200,000 of interest income.","For most non-financial companies, interest income is a small, non-operating item, shown separately from revenue from their main business. It is often reported net of interest expense as \\"net finance costs\\" or \\"net interest\\".","For banks and other lenders, interest income is the core of the business. It is their main source of revenue, and the difference between interest income and interest expense, called net interest income, is a key measure of their performance.","For individuals, interest income includes interest on savings accounts and bonds. In many countries it is taxable, although some accounts or allowances let people earn a certain amount of interest tax-free."],"note":"","total":1725,"prev":{"slug":"interest-expense","term":"Interest Expense"},"next":{"slug":"interest-only-loan","term":"Interest-Only Loan"}}')}}]);